INSERT INTO public.investigations (id, case_id, officer_id, update_type, notes, next_action) VALUES ('investigation-300-0', 'case-100', 'officer-admin', 'Initial Investigation', 'Inspected the scene of the incident. Noted surrounding conditions and collected initial CCTV listings. Case updates details.', 'Follow-up planned.') ON CONFLICT DO NOTHING;
INSERT INTO public.investigations (id, case_id, officer_id, update_type, notes, next_action) VALUES ('investigation-300-1', 'case-101', 'officer-006', 'Witness Interview', 'Interviewed complainant and witnesses present at the scene. Statements recorded and signed. Case updates details.', 'Follow-up planned.') ON CONFLICT DO NOTHING;
